from pathlib import Path
root=Path(__file__).resolve().parents[1]/'other/ai'
def edit(name, callback):
 p=root/name;p.write_text(callback(p.read_text(encoding='utf-8')),encoding='utf-8',newline='\n')
edit('harness_app/agent/runtime.py',lambda s:s.replace('args=["-m", "harness_app.mcp.server"]','args=[str(Path(__file__).resolve().parents[1] / "mcp/server.py")]'))
edit('harness_app/agent/external_mcp.py',lambda s:s.replace('["-m", "harness_app.mcp.server"]','[str(Path(__file__).resolve().parents[1] / "mcp/server.py")]'))
edit('harness_app/ui/settings.py',lambda s:s.replace('"deposition-sim"','"ai-harness"').replace('(*SAFE_ENVIRONMENT, "HARNESS_UI_PID",','(*SAFE_ENVIRONMENT, "AI_HARNESS_HOME", "HARNESS_UI_PID",').replace('["-m", "harness_app.mcp.desktop_endpoint",','[str(Path(__file__).resolve().parents[1] / "mcp/desktop_endpoint.py"),'))
edit('harness_app/mcp/desktop_endpoint.py',lambda s:s.replace('import argparse\n', 'import argparse\nfrom pathlib import Path\nimport sys\n\nif __package__ in (None, ""):\n    sys.path.insert(0, str(Path(__file__).resolve().parents[2]))\n').replace('deposition-sim','ai-harness'))
edit('harness_app/ui/taskbar.py',lambda s:s.replace('    arguments = list(sys.argv[1:])', '    arguments = list(sys.argv[1:])\n    if not launcher.is_file():\n        return subprocess.list2cmdline([str(executable), "-m", "harness_app", *arguments])'))
edit('harness_app/agent/development.py',lambda s:s.replace('"fastmcp-slim", "numpy", "matplotlib", "keyring", "ezdxf"','"fastmcp-slim", "keyring", "Pillow"'))
edit('tests/test_app.py',lambda s:s.replace('value=result.data', 'from harness_app.agent.tool_dispatch import result_value\n                value=result_value(result)').replace("for mode in ('chat','operate','research','question'):","for mode in ('chat','operate','research','question','delegate'):").replace("mode if mode!='question' else 'chat'", "'chat' if mode=='question' else 'operate' if mode=='delegate' else mode").replace("('fixture:question' if mode=='question' else 'fixture:tool '+mode)","('fixture:question' if mode=='question' else 'fixture:delegate' if mode=='delegate' else 'fixture:tool '+mode)"))
print('Fixed service discovery with independent state directories')